import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { useQuery } from '@tanstack/react-query'
import { toast } from 'sonner'
import { templatesService } from '@/integrations/supabase/templates'
import { projectsService } from '@/integrations/supabase/projects'
import { useTenant } from '@/app/providers/TenantProvider'
import { useIdentity } from '@/app/providers/IdentityProvider'
import { X } from 'lucide-react'

const schema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
})

type FormData = z.infer<typeof schema>
type Step = 'details' | 'template'
type Props = { onClose: () => void }

export function CreateProjectModal({ onClose }: Props) {
  const [step, setStep] = useState<Step>('details')
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null)
  const [templateSearch, setTemplateSearch] = useState('')
  const [details, setDetails] = useState<FormData | null>(null)
  const [creating, setCreating] = useState(false)
  const navigate = useNavigate()
  const { manifest } = useTenant()
  const { activeWorkspace, centralUser } = useIdentity()
  const workplaceId = activeWorkspace?.id

  const { register, handleSubmit, formState: { errors } } = useForm<FormData>({ resolver: zodResolver(schema) })

  const { data: templates = [] } = useQuery({
    queryKey: ['templates', manifest?.tenantId],
    queryFn: () => templatesService.listTemplates(manifest?.tenantId),
  })

  const filteredTemplates = templates.filter((t) => t.title.toLowerCase().includes(templateSearch.toLowerCase()))
  const onDetailsNext = handleSubmit((data) => { setDetails(data); setStep('template') })

  const onCreate = async () => {
    if (!details || !workplaceId || !manifest || !centralUser) {
      toast.error('Missing workplace, tenant, or user')
      return
    }
    setCreating(true)
    try {
      const project = await projectsService.createProject({
        workplaceId,
        tenantId: manifest.tenantId,
        ownerCentralId: centralUser.id,
        title: details.title,
        description: details.description,
        status: 'active',
      })
      // selectedTemplate currently unused server-side; reserved for next step
      void selectedTemplate
      toast.success('Project created!')
      onClose()
      navigate(`/app/project/${project.id}/organiser`)
    } catch (e) {
      toast.error((e as Error).message || 'Failed to create project')
    } finally {
      setCreating(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-surface rounded-2xl border border-border w-full max-w-lg shadow-xl">
        <div className="flex items-center justify-between p-5 border-b border-border">
          <div>
            <h2 className="font-semibold">Create project</h2>
            <p className="text-xs text-muted-foreground mt-0.5">Step {step === 'details' ? 1 : 2} of 2</p>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-muted"><X size={16} /></button>
        </div>

        <div className="flex gap-1 px-5 pt-4">
          {(['details', 'template'] as Step[]).map((s) => (
            <div key={s} className={`h-1 flex-1 rounded-full ${step === s || (s === 'details' && step === 'template') ? 'bg-accent' : 'bg-muted'}`} />
          ))}
        </div>

        <div className="p-5">
          {step === 'details' && (
            <form onSubmit={onDetailsNext} className="flex flex-col gap-4">
              <div>
                <label className="text-sm font-medium block mb-1.5">Project title *</label>
                <input {...register('title')} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" placeholder="e.g. Build MVP Platform" autoFocus />
                {errors.title && <p className="text-xs text-danger mt-1">{errors.title.message}</p>}
              </div>
              <div>
                <label className="text-sm font-medium block mb-1.5">Description <span className="text-muted-foreground">(optional)</span></label>
                <textarea {...register('description')} rows={3} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent resize-none" />
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <button type="button" onClick={onClose} className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground">Cancel</button>
                <button type="submit" className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90">Next</button>
              </div>
            </form>
          )}

          {step === 'template' && (
            <div className="flex flex-col gap-4">
              <div>
                <label className="text-sm font-medium block mb-1.5">Select a template <span className="text-muted-foreground">(optional)</span></label>
                <input value={templateSearch} onChange={(e) => setTemplateSearch(e.target.value)} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent mb-3" placeholder="Search templates..." />
                <div className="flex flex-col gap-2 max-h-56 overflow-y-auto">
                  {filteredTemplates.length === 0 && (
                    <p className="text-xs text-muted-foreground text-center py-4">No templates available. You can create a blank project.</p>
                  )}
                  {filteredTemplates.map((t) => (
                    <button key={t.id} onClick={() => setSelectedTemplate(t.id)}
                      className={`text-left rounded-xl border px-3 py-3 transition-colors ${selectedTemplate === t.id ? 'border-accent bg-accent/10' : 'border-border hover:border-accent/50'}`}>
                      <p className="text-sm font-medium">{t.title}</p>
                      <p className="text-xs text-muted-foreground mt-0.5">{t.description}</p>
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex justify-between gap-2 pt-2">
                <button onClick={() => setStep('details')} className="px-4 py-2 text-sm text-muted-foreground hover:text-foreground">Back</button>
                <button onClick={onCreate} disabled={creating} className="px-4 py-2 text-sm bg-accent text-accent-foreground rounded-lg hover:opacity-90 disabled:opacity-50">
                  {creating ? 'Creating…' : 'Create project'}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
